                            payload: components["schemas"]["TaskPayload"];
                            presentation?: components["schemas"]["TaskPresentation"] | null;
                            /**
                             * Format: int64
                             * @description Completed work units, in the unit the task defines.
                             */
                            progress_current: number;
                            /**
                             * Format: int32
                             * @description Derived progress in percent, clamped to 0-100; 0 when the total is unknown
                             *     and the task has not succeeded.
                             */
                            progress_percent: number;
                            /**
                             * Format: int64
                             * @description Total work units, in the unit the task defines; non-positive when unknown.
                             */
                            progress_total: number;
                            result?: components["schemas"]["TaskResult"] | null;
